# Simple Calculator (CLI)

def calculator():
    print("Simple Calculator")
    print("Operations: +  -  *  /  ** (power)  % (mod)")
    print("Type 'q' to quit.\n")

    while True:
        op = input("Enter operation (+, -, *, /, **, %) or q: ").strip()
        if op.lower() == "q":
            print("Bye!")
            break

        if op not in {"+", "-", "*", "/", "**", "%"}:
            print("Invalid operation.\n")
            continue

        try:
            a = float(input("Enter first number: "))
            b = float(input("Enter second number: "))
        except ValueError:
            print("Please enter valid numbers.\n")
            continue

        try:
            if op == "+":
                result = a + b
            elif op == "-":
                result = a - b
            elif op == "*":
                result = a * b
            elif op == "/":
                result = a / b
            elif op == "**":
                result = a ** b
            elif op == "%":
                result = a % b

            print(f"Result: {result}\n")

        except ZeroDivisionError:
            print("Error: Division by zero.\n")

if __name__ == "__main__":
    calculator()
```

If you want, I can also make a GUI calculator (Tkinter) or a calculator that parses full expressions like `2*(3+4)`.

